                    write_u32(memory, caps_ptr, caps_size); // dwSize
                    write_u32(memory, caps_ptr + 8, 0x00000018); // dwDevType: MOUSE
                    write_u32(memory, caps_ptr + 12, 3); // dwAxes: X, Y, Z
                    write_u32(memory, caps_ptr + 16, 8); // dwButtons: 8
                    write_u32(memory, caps_ptr + 20, 1); // dwPOVs: 1
