                        //   +36: rcNormalPosition right (i32)
                        //   +40: rcNormalPosition bottom (i32)
                        write_u32(memory, pwndpl, 44);       // length
                        write_u32(memory, pwndpl + 4, 0);     // flags
                        write_u32(memory, pwndpl + 8, placement.show_cmd);
                        write_i32(memory, pwndpl + 12, placement.pt_min_position.0);
                        write_i32(memory, pwndpl + 16, placement.pt_min_position.1);
                        write_i32(memory, pwndpl + 20, placement.pt_max_position.0);
                        write_i32(memory, pwndpl + 24, placement.pt_max_position.1);
                        write_i32(memory, pwndpl + 28, placement.rc_normal_position.left);
                        write_i32(memory, pwndpl + 32, placement.rc_normal_position.top);
                        write_i32(memory, pwndpl + 36, placement.rc_normal_position.right);
