                const SHGFI_ICON: u32 = 0x0000_0100;
                const SHGFI_SYSICONINDEX: u32 = 0x0000_4000;
                const SHGFI_USEFILEATTRIBUTES: u32 = 0x0000_0010;
                const SHGFI_EXETYPE: u32 = 0x0000_2000;
