                                write_u32(memory, pt_addr + 4, 0); // y
                                // Write initial effect
                                if effect_out != 0 {
                                    write_u32(memory, effect_out, allowed_effects);
                                }
                                let _ = self.execute_guest_callback(
                                    state, memory, drag_enter,
                                    &[drop_target, data_obj, 0, pt_addr, effect_out],
                                    "IDropTarget::DragEnter",
                                );
