                self.last_error = 0;
                self.push_trace(
                    "ole32",
                    "DoDragDrop",
                    BTreeMap::from([
                        ("data_obj".to_string(), json!(format!("{data_obj:#x}"))),
                        ("allowed_effects".to_string(), json!(allowed_effects)),
                    ]),
                    json!(0),
                );
